import path4 from "node:path";
import { fileURLToPath as fileURLToPath2 } from "node:url";
var AgentTokenStoreError = class extends Error {
  constructor(message = "The agent token operation failed.") {
    super(message);
    this.name = "AgentTokenStoreError";
  }
};
var TOKEN_MIGRATION_LOCK_ID = 824392842;
async function migrateAgentTokens(sql, options = {}) {
  try {
    const dir = path4.join(path4.dirname(fileURLToPath2(import.meta.url)), "team-memory-migrations");
    const migrations = readMigrationFiles(dir, options.files);
    const files = Object.keys(migrations).sort();
    await migrateAccessSchema(sql, options.accessMigrations);
    const [presence] = await sql`SELECT to_regclass('kybero_cockpit_access.agent_token_migrations') IS NOT NULL AS present`;
    if (presence?.present) {
      const rows = await sql`SELECT name FROM kybero_cockpit_access.agent_token_migrations`;
      const applied = new Set(rows.map((row) => row.name));
      if (files.every((name) => applied.has(name))) return [];
    }
    return await sql.begin(async (tx) => {
      await tx`SELECT pg_advisory_xact_lock(${TOKEN_MIGRATION_LOCK_ID})`;
      await tx`CREATE TABLE IF NOT EXISTS kybero_cockpit_access.agent_token_migrations
        (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now())`;
      const applied = await tx`SELECT name FROM kybero_cockpit_access.agent_token_migrations`;
      const names = new Set(applied.map((row) => row.name));
      const newlyApplied = [];
      for (const file2 of files) {
        if (names.has(file2)) continue;
        await tx.unsafe(migrations[file2]);
        await tx`INSERT INTO kybero_cockpit_access.agent_token_migrations (name) VALUES (${file2})`;
        newlyApplied.push(file2);
      }
      return newlyApplied;
    });
  } catch (error62) {
    if (error62?.code === "42501") {
      throw new AgentTokenStoreError(
        "Agent token schema needs owner access. Run pnpm db:migrate before starting the API or worker."
      );
    }
    throw new AgentTokenStoreError();
  }
}

