async function grantTeamMemoryRole(sql, role, profile) {
  await assertTeamMemoryDatabaseActive(sql);
  const quoted2 = quoteTeamMemoryIdentifier(role);
  await assertTeamMemoryRolePrivileges(sql, profile, role);
  await sql.unsafe(`GRANT USAGE ON SCHEMA cockpit_memory, kybero_cockpit_access TO ${quoted2}`);
  if (profile === "operator")
    await sql.unsafe(`GRANT SELECT ON ALL TABLES IN SCHEMA cockpit_memory TO ${quoted2}`);
  for (const grant of grantsFor(profile)) {
    const columns = grant.columns ? ` (${grant.columns.map(quoteTeamMemoryIdentifier).join(", ")})` : "";
    const table = grant.table.split(".").map(quoteTeamMemoryIdentifier).join(".");
    await sql.unsafe(`GRANT ${grant.privilege}${columns} ON ${table} TO ${quoted2}`);
  }
  if (profile !== "reader")
    await sql.unsafe(
      `GRANT USAGE ON SEQUENCE cockpit_memory.sync_events_event_seq_seq TO ${quoted2}`
    );
  await assertTeamMemoryRolePrivileges(sql, profile, role);
}

// apps/api/src/code23/team-memory-bootstrap.ts
function parseTeamMemoryBootstrapArgs(argv) {
  const names = [
    "workspace",
    "name",
    "owner",
    "reader-role",
    "submitter-role",
    "operator-role"
  ];
  const { values: values2, tokens } = parseArgs({
    args: argv,
    strict: true,
    allowPositionals: false,
    tokens: true,
    options: Object.fromEntries(names.map((name) => [name, { type: "string" }]))
  });
  if (names.some(
    (name) => typeof values2[name] !== "string" || !values2[name]?.trim() || tokens.filter((token) => token.kind === "option" && token.name === name).length !== 1
  )) {
    throw new Error("Explicit workspace, name, owner and three database roles are required");
  }
  const input2 = {
    workspaceId: values2.workspace,
    name: values2.name,
    ownerUserId: values2.owner,
    roles: {
      reader: values2["reader-role"],
      submitter: values2["submitter-role"],
      operator: values2["operator-role"]
    }
  };
  validateInput(input2);
  return input2;
}
function validateInput(input2) {
  if (!/^[a-z][a-z0-9-]{1,39}$/.test(input2.workspaceId) || /^[0-9a-f]{32}$/.test(input2.workspaceId) || /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(input2.workspaceId) || input2.name.trim().length === 0 || input2.name.trim().length > 120 || !input2.ownerUserId.trim() || input2.ownerUserId.length > 200 || /[\p{Cc}\p{Cf}]/u.test(input2.name + input2.ownerUserId))
    throw new Error("Invalid team memory bootstrap identity");
  validateTeamMemoryRoles(input2.roles);
}
async function bootstrapTeamMemory(sql, input2) {
  validateInput(input2);
  const memoryFiles = readMigrationFiles("", input2.migrations.memory);
  const accessFiles = readMigrationFiles("", input2.migrations.access);
  const tokenFiles = readMigrationFiles("", input2.migrations.tokens);
  try {
    await assertTeamMemoryDatabaseActive(sql);
    return await sql.begin("isolation level read committed", async (tx) => {
      await tx`SELECT pg_advisory_xact_lock(${TEAM_MEMORY_SETUP_LOCK_ID})`;
      const scoped = new Proxy(tx, {
        get(target, property) {
          if (property === "begin") return target.savepoint.bind(target);
          return Reflect.get(target, property);
        }
      });
      await assertTeamMemoryDatabaseActive(scoped);
      for (const profile of ["reader", "submitter", "operator"]) {
        await assertTeamMemoryRolePrivileges(scoped, profile, input2.roles[profile]);
      }
      const memory = await runSchemaMigrations(
        {
          sql: scoped,
          query: async (text2, params = []) => await scoped.unsafe(text2, params),
          execute: async (text2, params = []) => {
            const result = await scoped.unsafe(text2, params);
            return { rowCount: result.count };
          },
          close: async () => {
          }
        },
        {
          schema: "cockpit_memory",
          advisoryLockId: COCKPIT_MEMORY_MIGRATION_LOCK_ID,
          migrationsDir: "",
          label: "Cockpit memory",
          files: memoryFiles
        }
      );
      const access = await migrateAccessSchema(scoped, { files: accessFiles });
      const tokens = await migrateAgentTokens(scoped, {
        files: tokenFiles,
        accessMigrations: { files: accessFiles }
      });
      const workspaces = createPostgresWorkspaceStore(scoped);
      let workspaceCreated = false;
      if (!await workspaces.getWorkspace(input2.workspaceId)) {
        const created = await workspaces.createWorkspace({
          id: input2.workspaceId,
          name: input2.name.trim(),
          ownerUserId: input2.ownerUserId
        });
        if (!created.ok) throw new Error("Could not create team memory workspace");
        workspaceCreated = true;
      }
      if (await workspaces.roleFor(input2.workspaceId, input2.ownerUserId) !== "owner")
        throw new Error("Team memory workspace owner conflicts with bootstrap identity");
      for (const profile of ["reader", "submitter", "operator"]) {
        await grantTeamMemoryRole(scoped, input2.roles[profile], profile);
      }
      for (const profile of ["reader", "submitter", "operator"]) {
        await assertTeamMemoryRolePrivileges(scoped, profile, input2.roles[profile]);
      }
      return { workspaceCreated, applied: { memory, access, tokens } };
    });
  } catch {
    throw new Error(
      "Could not bootstrap team memory; verify protected database access, role restrictions and owner identity"
    );
  }
}

// apps/api/src/code23/team-memory-bootstrap-cli.ts
async function main() {
  const input2 = parseTeamMemoryBootstrapArgs(process.argv.slice(2));
  const databaseUrl = process.env.DATABASE_URL?.trim();
  if (!databaseUrl) throw new Error("Protected DATABASE_URL is required");
  const sql = src_default(databaseUrl, { max: 1, onnotice: () => {
  }, connect_timeout: 5 });
  try {
    await bootstrapTeamMemory(sql, { ...input2, migrations: define_TEAM_MEMORY_BUNDLED_MIGRATIONS_default });
    process.stdout.write("Team memory bootstrap completed\n");
  } finally {
    await sql.end({ timeout: 5 });
  }
}
void main().catch(() => {
  process.stderr.write("Could not bootstrap team memory\n");
  process.exitCode = 1;
});
